mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("add4 add9 remove4 add7","7,9"),
        ("add1 add2 remove2 add3","1,3"),
        ("add1 add1 add2 remove1","2"),
        ("add3 add4 remove9","3,4"),
        ("add7 remove7 add8","8"),
        ("  \nadd4 add9 remove4 add7\n  ","7,9"),
        ("\nadd7 remove7 add8\n","8")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS randomized-set");
}
